commands.command:
cp -p /etc/nftables.nft /etc/nftables.nft.package-default && cat > /etc/nftables.nft <<'ANTRIEB_NFT_EOF'
#!/usr/sbin/nft -f

flush ruleset

table inet host_firewall {
    chain input {
        type filter hook input priority filter; policy drop;

        iifname "lo" counter accept comment "allow loopback"
        ct state established,related counter accept comment "allow established and related"
        ct state invalid counter drop comment "drop invalid packets"

        ip protocol udp udp sport 67 udp dport 68 counter accept comment "allow DHCPv4 replies"
        ip6 nexthdr icmpv6 icmpv6 type { nd-router-solicit, nd-router-advert, nd-neighbor-solicit, nd-neighbor-advert } counter accept comment "allow IPv6 neighbor discovery"

        tcp dport { 22, 8080 } ct state new counter accept comment "allow SSH and TCP 8080"

        counter reject with icmpx type port-unreachable comment "reject all other inbound traffic"
    }

    chain forward {
        type filter hook forward priority filter; policy drop;
    }

    chain output {
        type filter hook output priority filter; policy accept;
    }
}
ANTRIEB_NFT_EOF
chmod 600 /etc/nftables.nft
nft -c -f /etc/nftables.nft
printf 'config_sha256='; sha256sum /etc/nftables.nft | awk '{print $1}'

